import { spawn } from "node:child_process"
import { Buffer } from "node:buffer"
import console from "node:console"
import { mkdtemp, readFile, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join, resolve } from "node:path"
import process from "node:process"
import { pathToFileURL } from "node:url"

/** Compares exact generated bytes without modifying the source file. */
export async function checkGeneratedBindings({ targetPath, generate }) {
  const absoluteTargetPath = resolve(targetPath)
  const originalBytes = await readFile(absoluteTargetPath)
  let generatedBytes
  let generationError

  try {
    generatedBytes = await generate()
  } catch (error) {
    generationError = error
  }

  let currentBytes
  try {
    currentBytes = await readFile(absoluteTargetPath)
  } catch (error) {
    throw new Error("SOURCE_CHANGED_DURING_CHECK: bindings source is no longer available", {
      cause: error,
    })
  }
  if (!currentBytes.equals(originalBytes)) {
    throw new Error("SOURCE_CHANGED_DURING_CHECK: bindings source changed while the check ran")
  }

  if (generationError) throw generationError
  if (!Buffer.isBuffer(generatedBytes)) {
    throw new TypeError("The bindings generator must return a Buffer")
  }
  if (!generatedBytes.equals(originalBytes)) {
    throw new Error(
      "Generated IPC bindings are stale; run the bindings export test and review the result.",
    )
  }
}

function runCargoExport(cwd, outputPath) {
  return new Promise((resolvePromise, rejectPromise) => {
    const child = spawn(
      "cargo",
      ["test", "--manifest-path", join(cwd, "src-tauri/Cargo.toml"), "export_bindings"],
      {
        cwd,
        env: { ...process.env, AMBY_BINDINGS_OUTPUT: outputPath },
        stdio: "inherit",
      },
    )
    child.once("error", rejectPromise)
    child.once("close", (code, signal) => {
      if (code === 0) resolvePromise()
      else
        rejectPromise(
          new Error(`Bindings export failed${signal ? ` (${signal})` : ` (exit ${code})`}`),
        )
    })
  })
}

async function main() {
  const cwd = process.cwd()
  const targetPath = join(cwd, "src/lib/bindings.ts")
  await checkGeneratedBindings({
    targetPath,
    generate: async () => {
      const temporaryDirectory = await mkdtemp(join(tmpdir(), "amby-bindings-check-"))
      const outputPath = join(temporaryDirectory, "bindings.ts")
      try {
        await runCargoExport(cwd, outputPath)
        return await readFile(outputPath)
      } finally {
        await rm(temporaryDirectory, { recursive: true, force: true })
      }
    },
  })
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : "Bindings check failed")
    process.exitCode = 1
  })
}
